-- ============================================================
-- Jean Legacy Import — DRY RUN (safe to run, nothing is saved)
-- Everything is wrapped in a transaction that ROLLS BACK.
-- No rows will be permanently inserted.
-- Run on: Production phpMyAdmin → platetag_db1 → SQL tab
-- ============================================================

START TRANSACTION;

-- Step 1: Create the discovery session
VALUES (7, 'Legacy Import — Pre-App Sightings', 0, NOW(), NOW());

SET @session_id = LAST_INSERT_ID();

-- Step 2: Insert 235 sightings

-- Check counts inside the transaction (before rollback)
SELECT COUNT(*) AS rows_that_would_insert
FROM user_discovered_plates
WHERE session_id = @session_id AND user_id = 7;

SELECT @session_id AS session_id_that_would_be_created;

-- ROLLBACK cancels everything above — nothing is saved
ROLLBACK;

-- Confirm the session was NOT saved
SELECT COUNT(*) AS sessions_saved_should_be_0
FROM discovery_sessions
WHERE user_id = 7 AND name = 'Legacy Import — Pre-App Sightings';
